#!/usr/bin/python3

def check_property(f, p, k):
    for i in range(p):
        if f[(k * i) % p] != (k * f[i]) % p:
            return False
    return True

def recursive_count(f, p, k, i):
    if i == p:
        return check_property(f, p, k)
    total = 0
    for j in range(p):
        f.append(j)
        total += recursive_count(f, p, k, i + 1)
        f.pop()
    return total

def main(p, k):
    count = 0
    visited = set()
    for j in range(p):
        if j not in visited:
            count += 1
        current = j
        while current not in visited:
            visited.add(current)
            current = (current * k) % p
    return pow(p, count - (k != 1), 10 ** 9 + 7)

p, k = map(int, input().split())
print(main(p, k))
